from rewards.pbebench import reward
from collections import Counter
import itertools

def find_single_replacements(input_str, output_str):
    """Find all (old, new) pairs where input.replace(old, new) == output"""
    if input_str == output_str:
        return []

    candidates = set()
    n_in = len(input_str)
    n_out = len(output_str)

    for i in range(n_in):
        for j in range(i + 1, min(i + 4, n_in + 1)):
            old = input_str[i:j]
            for i2 in range(n_out):
                for j2 in range(i2 + 1, min(i2 + 4, n_out + 1)):
                    new = output_str[i2:j2]
                    if input_str.replace(old, new) == output_str:
                        candidates.add((old, new))
            if input_str.replace(old, '') == output_str:
                candidates.add((old, ''))

    return list(candidates)

def apply_programs(inputs, programs):
    """Apply a sequence of programs to all inputs"""
    results = []
    for inp in inputs:
        cur = inp
        for pred, transform in programs:
            cur = cur.replace(pred, transform)
        results.append(cur)
    return results

def score_programs(inputs, outputs, programs, max_programs=5):
    """Score a program sequence against examples"""
    return reward(programs, True, {"inputs": inputs, "outputs": outputs},
                  max_programs=max_programs)

# Test greedy approach
inputs = ["zakX", "iyF", "FJjT", "Otaak", "zXro", "zpCvG", "ncXr", "MeIaWg", "pWGLqA", "yOvBjs", "txW", "uYMTTs", "GUtx"]
outputs = ["NVeX", "iCNq", "FNT", "Otaae", "zmo", "lNCvG", "ncm", "MemWg", "pWDqA", "yOKhfs", "tAQE", "uNtMTTs", "cZtx"]

# Find all single replacements for each pair
all_candidates = []
for inp, out in zip(inputs, outputs):
    cands = find_single_replacements(inp, out)
    for c in cands:
        all_candidates.append(c)

# Count frequency
freq = Counter(all_candidates)
print("Top candidates by frequency:")
for c, count in freq.most_common(20):
    print(f"  replace('{c[0]}', '{c[1]}'): fixes {count} pairs")

# Check how many unique pairs we can fix with top candidates
print("\nChecking top-5 candidates:")
for combo in itertools.combinations(freq.keys(), 5):
    result = apply_programs(inputs, combo)
    correct = sum(1 for r, o in zip(result, outputs) if r == o)
    if correct >= 12:
        print(f"  {combo} -> {correct}/13 correct")

