def find_single_replacements(input_str, output_str):
    if input_str == output_str:
        return []

    candidates = set()
    n_in = len(input_str)
    n_out = len(output_str)

    for i in range(n_in):
        for j in range(i + 1, min(i + 4, n_in + 1)):
            old = input_str[i:j]
            for i2 in range(n_out):
                for j2 in range(i2 + 1, min(i2 + 4, n_out + 1)):
                    new = output_str[i2:j2]
                    if input_str.replace(old, new) == output_str:
                        candidates.add((old, new))
            if input_str.replace(old, '') == output_str:
                candidates.add((old, ''))

    return list(candidates)

def apply_programs_to_str(s, programs):
    for old, new in programs:
        s = s.replace(old, new)
    return s

def evaluate_programs(inputs, outputs, programs):
    """Evaluate programs against all examples"""
    correct = sum(1 for inp, out in zip(inputs, outputs) if apply_programs_to_str(inp, programs) == out)
    return correct / len(inputs)

def beam_search_v2(inputs, outputs, max_programs=20, beam_width=100):
    """Beam search with pruning and multi-step candidates"""
    n = len(inputs)
    if n == 0:
        return [], 0.0

    best_programs = []
    best_score = evaluate_programs(inputs, outputs, [])

    # State: (programs_tuple, current_states_tuple)
    beam = [(tuple(), tuple(inputs))]
    visited = set([tuple()])

    for step in range(max_programs):
        if best_score >= 1.0:
            break

        next_beam = []
        all_cands = set()

        # Collect candidates from ALL current states
        for programs, states in beam:
            for i, (cur_state, expected) in enumerate(zip(states, outputs)):
                if cur_state == expected:
                    continue
                cands = find_single_replacements(cur_state, expected)
                for c in cands:
                    all_cands.add(c)

        if not all_cands:
            break

        # Expand
        seen_next = set()
        for programs, states in beam:
            for cand in all_cands:
                new_programs = programs + (cand,)
                if new_programs in visited:
                    continue
                visited.add(new_programs)

                new_states = tuple(apply_programs_to_str(s, [cand]) for s in states)
                score = sum(1 for ns, exp in zip(new_states, outputs) if ns == exp)
                next_beam.append((new_programs, new_states, score))

                if score > evaluate_programs(inputs, outputs, list(new_programs)):
                    pass  # already counted

        if not next_beam:
            break

        # Sort by score (descending) and keep top beam_width
        next_beam.sort(key=lambda x: -x[2])
        beam = [(p, s) for p, s, sc in next_beam[:beam_width]]

        # Update best
        for programs, states in beam:
            sc = sum(1 for s, exp in zip(states, outputs) if s == exp)
            if sc / n > best_score:
                best_score = sc / n
                best_programs = programs

    return list(best_programs), best_score

