import random
import time

def find_single_replacements(input_str, output_str):
    """Find all (old, new) pairs where input.replace(old, new) == output"""
    if input_str == output_str:
        return []

    candidates = set()
    n_in = len(input_str)
    n_out = len(output_str)

    for i in range(n_in):
        for j in range(i + 1, min(i + 4, n_in + 1)):
            old = input_str[i:j]
            for i2 in range(n_out):
                for j2 in range(i2 + 1, min(i2 + 4, n_out + 1)):
                    new = output_str[i2:j2]
                    if input_str.replace(old, new) == output_str:
                        candidates.add((old, new))
            if input_str.replace(old, '') == output_str:
                candidates.add((old, ''))

    return list(candidates)

def apply_programs_to_str(s, programs):
    for old, new in programs:
        s = s.replace(old, new)
    return s

def evaluate_programs(inputs, outputs, programs):
    """Evaluate programs against all examples"""
    correct = sum(1 for inp, out in zip(inputs, outputs) if apply_programs_to_str(inp, programs) == out)
    return correct, len(inputs)

def beam_search_search(inputs, outputs, max_programs=15, beam_width=200, max_time=30):
    """
    Beam search over program sequences.
    State: (programs_tuple, current_states_tuple, score)
    """
    n = len(inputs)
    if n == 0:
        return [], 0.0

    start_time = time.time()
    best_programs = []
    best_score = 0

    # Initial state
    initial_states = tuple(inputs)
    initial_fixed = sum(1 for s, exp in zip(initial_states, outputs) if s == exp)

    # Beam: list of (programs, states, fixed_count)
    beam = [(tuple(), initial_states, initial_fixed)]

    while time.time() - start_time < max_time:
        if not beam:
            break

        # Check if any state in beam is perfect
        for programs, states, score in beam:
            if score == n:
                return list(programs), 1.0

        # Collect all unique candidates from current beam states
        all_cands = set()
        for programs, states, _ in beam:
            for i, (cur_state, expected) in enumerate(zip(states, outputs)):
                if cur_state == expected:
                    continue
                cands = find_single_replacements(cur_state, expected)
                for c in cands:
                    all_cands.add(c)

        if not all_cands:
            break

        # Expand beam
        next_beam = []
        for programs, states, score in beam:
            for cand in all_cands:
                # Check if this candidate is in programs already (avoid duplicates at same position)
                if cand in programs:
                    continue

                new_states = tuple(apply_programs_to_str(s, [cand]) for s in states)
                new_fixed = sum(1 for ns, exp in zip(new_states, outputs) if ns == exp)
                new_programs = programs + (cand,)

                if new_fixed >= score:  # at least maintain score
                    next_beam.append((new_programs, new_states, new_fixed))

        if not next_beam:
            break

        # Sort and keep top beam_width by fixed count, then by program length
        next_beam.sort(key=lambda x: (-x[2], x[0]))
        beam = next_beam[:beam_width]

        # Update best
        for programs, states, score in beam:
            sc = score / n
            if sc > best_score:
                best_score = sc
                best_programs = list(programs)

    return best_programs, best_score

